require __DIR__.'/includes/module.php';$u=require_auth();require_permission('invoices.view');if($_SERVER['REQUEST_METHOD']==='POST')require_permission('invoices.edit');$bid=(int)$u['business_id'];$pdo=db();$q=$pdo->prepare('SELECT i.*,c.name customer,c.company,c.email,c.phone,c.city,c.gstin FROM invoices i JOIN customers c ON c.id=i.customer_id WHERE i.id=? AND i.business_id=?');$q->execute([(int)($_GET['id']??0),$bid]);$inv=$q->fetch();if(!$inv){http_response_code(404);exit('Invoice not found.');}$q=$pdo->prepare('SELECT * FROM invoice_items WHERE invoice_id=?');$q->execute([$inv['id']]);$items=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM payments WHERE invoice_id=? AND business_id=? AND reversed_at IS NULL ORDER BY paid_at DESC');$q->execute([$inv['id'],$bid]);$payments=$q->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='void'&&$inv['status']==='Issued'&&(float)$inv['amount_paid']===0.0){$pdo->prepare("UPDATE invoices SET status='Void' WHERE id=? AND business_id=?")->execute([$inv['id'],$bid]);audit('invoice.void',$inv['invoice_number']);flash('Invoice voided.');redirect('invoices.php');}elseif(($_POST['action']??'')==='void')$error='Only unpaid issued invoices can be voided. Correct paid invoices through an adjustment workflow.';}$biz=json_decode($inv['business_snapshot']?:'{}',true)?:[];$cust=json_decode($inv['customer_snapshot']?:'{}',true)?:[];$cg=$sg=$ig=0.0;foreach($items as $it){$cg+=(float)($it['cgst_amount']??0);$sg+=(float)($it['sgst_amount']??0);$ig+=(float)($it['igst_amount']??0);}
page_start($inv['invoice_number'],'invoices');module_css('invoice-view');?>
<div class="section-head no-print"><div><span class="eyebrow">INVOICE DETAILS</span><h1><?=e($inv['invoice_number'])?></h1><p><?=e($inv['customer'])?> · issued <?=fmt_date($inv['invoice_date'])?></p></div><div style="display:flex;gap:8px"><a class="button secondary" href="invoice-pdf.php?id=<?=(int)$inv['id']?>"><i class="ti ti-download"></i> Download PDF</a><button class="button secondary" onclick="window.print()"><i class="ti ti-printer"></i> Print</button><a class="button secondary" href="payments.php?invoice=<?=(int)$inv['id']?>">Record payment</a><a class="button secondary" href="invoices.php">Back</a></div></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif?>
<article class="invoice-paper"><div class="invoice-brand"><div><span class="brand-mark"><i class="ti ti-chart-dots-3"></i></span><strong><?=e($biz['legal_name']??$biz['name']??'BUZNET CRM')?></strong></div><span class="status <?=strtolower(str_replace(' ','-',e($inv['status'])))?>"><?=e($inv['status'])?></span></div><p><b><?=e($inv['document_type']??'Invoice')?></b><?php if($inv['place_of_supply_state']):?> · Place of supply: <?=e($inv['place_of_supply_state'])?> (<?=e($inv['place_of_supply_code'])?>)<?php endif?></p><div class="invoice-meta"><div><small>SUPPLIER</small><strong><?=e($biz['legal_name']??$biz['name']??'')?></strong><span><?=e($biz['address']??'')?><?=!empty($biz['city'])?'<br>'.e($biz['city']):''?><?=!empty($biz['state'])?'<br>'.e($biz['state']):''?><?=!empty($biz['gstin'])?'<br>GSTIN: '.e($biz['gstin']):''?></span></div><div><small>BILL TO</small><strong><?=e($cust['name']??$inv['customer'])?></strong><span><?=e($cust['company']??$inv['company']??'')?><?=!empty($cust['address'])?'<br>'.e($cust['address']):''?><?=!empty($cust['city'])?'<br>'.e($cust['city']):''?><?=!empty($cust['state'])?'<br>'.e($cust['state']):''?><?=!empty($cust['gstin'])?'<br>GSTIN: '.e($cust['gstin']):''?></span></div><div><small>INVOICE DATE</small><strong><?=fmt_date($inv['invoice_date'])?></strong><small style="margin-top:14px">DUE DATE</small><strong><?=fmt_date($inv['due_date'])?></strong></div></div>
<div class="table-scroll"><table class="data-table"><thead><tr><th>DESCRIPTION / HSN-SAC</th><th>QTY</th><th>RATE</th><th>CGST</th><th>SGST</th><th>IGST</th><th>AMOUNT</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td class="table-strong"><?=e($it['description'])?><div class="help-text">HSN/SAC: <?=e($it['hsn_sac']??'—')?> · Total GST rate <?=e($it['tax_rate'])?>%</div></td><td><?=e($it['quantity'])?> <?=e($it['unit'])?></td><td><?=money($it['unit_price'])?></td><td><?=e($it['cgst_rate']??0)?>% · <?=money($it['cgst_amount']??0)?></td><td><?=e($it['sgst_rate']??0)?>% · <?=money($it['sgst_amount']??0)?></td><td><?=e($it['igst_rate']??0)?>% · <?=money($it['igst_amount']??0)?></td><td class="table-strong"><?=money($it['line_total'])?></td></tr><?php endforeach?></tbody></table></div><div class="invoice-sums"><span>Taxable value <b><?=money($inv['subtotal'])?></b></span><span>CGST <b><?=money($cg)?></b></span><span>SGST <b><?=money($sg)?></b></span><span>IGST <b><?=money($ig)?></b></span><strong>Total <b><?=money($inv['total'])?></b></strong><span>Paid <b><?=money($inv['amount_paid'])?></b></span><strong class="due">Balance due <b><?=money((float)$inv['total']-(float)$inv['amount_paid'])?></b></strong></div><?php if($inv['notes']):?><div class="invoice-notes"><small>NOTES</small><p><?=nl2br(e($inv['notes']))?></p></div><?php endif?></article>
<section class="content-card" style="margin-top:15px"><h2>Payment history</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>AMOUNT</th><th>METHOD</th><th>REFERENCE</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=fmt_date($p['paid_at'])?></td><td><?=money($p['amount'])?></td><td><?=e($p['method'])?></td><td><?=e($p['reference']?:'—')?></td></tr><?php endforeach;if(!$payments):?><tr><td colspan="4" class="empty-row">No payments recorded.</td></tr><?php endif?></tbody></table></div></section><?php if($inv['status']==='Issued'&&(float)$inv['amount_paid']===0.0):?><form method="post" class="no-print" style="margin-top:15px" onsubmit="return confirm('Void this unpaid invoice? This will exclude it from active sales.')"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="void"><button class="link-button" style="color:#bd665e">Void invoice</button></form><?php endif?><style>.invoice-paper{background:#fff;border:1px solid #edf0f2;border-radius:9px;padding:32px;max-width:1100px}.invoice-brand{display:flex;justify-content:space-between;align-items:center;padding-bottom:22px;border-bottom:1px solid #edf0f2}.invoice-brand>div{display:flex;align-items:center;gap:10px}.invoice-brand strong{font:700 15px var(--display)}.invoice-meta{display:flex;justify-content:space-between;padding:23px 0;gap:18px}.invoice-meta>div{display:flex;flex-direction:column;align-items:flex-start;max-width:38%}.invoice-meta small,.invoice-notes small{font-size:8px;letter-spacing:1px;color:#9aa4ae;font-weight:700}.invoice-meta strong{font-size:11px;margin:5px 0}.invoice-meta span{font-size:10px;color:#83909d;line-height:1.8}.invoice-sums{width:min(330px,100%);margin:15px 0 0 auto;display:grid;gap:9px}.invoice-sums span,.invoice-sums strong{display:flex;justify-content:space-between;font-size:10px;color:#87919c}.invoice-sums strong{font-size:12px;color:#334050;border-top:1px solid #eef0f2;padding-top:10px}.invoice-sums .due{color:#2889c5}.invoice-notes{border-top:1px solid #eef0f2;padding-top:15px;margin-top:22px}.invoice-notes p{font-size:10px;color:#7b8794}@media print{.sidebar,.topbar,.no-print{display:none!important}.main{margin:0}.page-content{padding:0}.invoice-paper,.content-card{box-shadow:none;border:0}}
</style><?php page_end();
